  "headline": "Succinylcholine chloride is not on FDA's shortage list; Fresenius Kabi discontinued its product on 2026-07-23 and a registered plant for Eugia Pharma Specialities Limited was classified OAI on 2026-02-06",
  "headline_cites": ["D3", "E13", "E12"],
  "sentences": [
    {
      "text": "FDA's drug shortage list shows succinylcholine chloride is not listed as of 2026-10-21.",
      "cites": ["D3"]
    },
    {
      "text": "Fresenius Kabi USA, LLC posted a discontinuation of its succinylcholine chloride injection on 2026-07-23.",
      "cites": ["E13"]
    },
    {
      "text": "A registered plant for Eugia Pharma Specialities Limited (FEI 3008461619) was classified OAI after an inspection ending 2026-02-06.",
      "cites": ["E12", "E10"]
    },
    {
      "text": "The same plant received a Warning Letter on 2024-08-15 following an earlier OAI inspection ending 2024-02-02.",
      "cites": ["E11", "E8"]
    },
    {
      "text": "Corvale East has 20.5 days on hand and Corvale General has 26.1 days on hand at current usage.",
      "cites": ["D1", "D2"]
    },
    {
      "text": "The top-ranked purchasing option is BE Pharmaceuticals Inc., which is not on the FDA shortage list today.",
      "cites": ["D4"]
    },
    {
      "text": "Verify that BE Pharmaceuticals Inc. can supply the needed presentation and confirm its manufacturing site status before ordering.",
      "cites": ["D4"]
    }
  ]
}
